#!/usr/bin/env bash
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). Apache-2.0.
# Installs VRChat Stream for the current user (no root). Run it on every
# computer you use: the one with the window and the one that streams.
set -euo pipefail
SRC="$(cd "$(dirname "$0")" && pwd)"
APP="$HOME/.local/share/vrchat-stream"
BIN="$HOME/.local/bin"

say() { echo "• $*"; }
command -v python3 >/dev/null || { echo "python3 is required / потрібен python3"; exit 1; }

say "Copying files / Копіюю файли → $APP"
mkdir -p "$APP/server" "$BIN" "$HOME/.local/share/applications"
cp "$SRC/vrchat_stream.py" "$SRC/LICENSE" "$SRC/NOTICE" "$SRC/uninstall.sh" "$APP/"
cp "$SRC"/server/*.sh "$SRC"/server/*.py "$APP/server/"
chmod +x "$APP/vrchat_stream.py" "$APP/server/stream.sh"

cat > "$BIN/vrchat-stream" <<EOF
#!/bin/sh
exec python3 -I "$APP/vrchat_stream.py" "\$@"
EOF
chmod +x "$BIN/vrchat-stream"

cat > "$HOME/.local/share/applications/vrchat-stream.desktop" <<EOF
[Desktop Entry]
Type=Application
Name=VRChat Stream
Name[uk]=Трансляція у VRChat
Comment=Show a browser, screen, window or region in the VRChat video player
Comment[uk]=Показати браузер, екран, вікно або область у плеєрі VRChat
Exec=$BIN/vrchat-stream
Icon=media-playback-start
Categories=AudioVideo;Video;
StartupWMClass=vrchat-stream
EOF

if ! python3 -c "import PySide6" 2>/dev/null; then
  say "Installing PySide6 for the window / Встановлюю PySide6 для вікна"
  python3 -m pip install -q --user --disable-pip-version-check PySide6 2>/dev/null || \
    echo "  ! Could not install PySide6 — install it with your package manager / встанови PySide6"
fi

# What the streaming side needs
missing=()
for c in ffmpeg cloudflared pactl curl Xwayland; do command -v $c >/dev/null || missing+=("$c"); done
browser=no
for b in brave-browser brave chromium-browser chromium google-chrome-stable google-chrome; do
  command -v $b >/dev/null && browser=yes
done
[ $browser = yes ] || missing+=("chromium (or Brave / Chrome)")
python3 -c 'import dbus, gi; gi.require_version("Gst", "1.0"); from gi.repository import Gst' 2>/dev/null \
  || missing+=("python3-dbus + python3-gobject + gstreamer")
command -v wl-copy >/dev/null || missing+=("wl-clipboard (optional)")

echo
echo "Done / Готово. Menu → «VRChat Stream» / «Трансляція у VRChat»"
if [ ${#missing[@]} -gt 0 ]; then
  echo
  echo "To stream FROM this computer these are still needed / Щоб транслювати З цього комп'ютера, ще потрібно:"
  printf '  - %s\n' "${missing[@]}"
  echo "  Fedora: sudo dnf install ffmpeg cloudflared Xwayland chromium python3-dbus python3-gobject pipewire-gstreamer gstreamer1-plugins-good gstreamer1-plugins-bad-free gstreamer1-plugin-openh264 wl-clipboard"
  echo "  Ubuntu/Debian: sudo apt install ffmpeg xwayland chromium python3-dbus python3-gi gstreamer1.0-pipewire gstreamer1.0-plugins-good gstreamer1.0-plugins-bad gstreamer1.0-plugins-ugly wl-clipboard"
  echo "  Arch: sudo pacman -S ffmpeg cloudflared xorg-xwayland chromium python-dbus python-gobject gst-plugin-pipewire gst-plugins-good gst-plugins-bad gst-plugins-ugly wl-clipboard"
  echo "  cloudflared: https://developers.cloudflare.com/cloudflare-one/connections/connect-networks/downloads/"
fi
echo "Uninstall / Видалити: bash $APP/uninstall.sh"
